function giftSection(){let perPage=8,start=giftPage*perPage,visible=gifts.slice(start,start+perPage),maxPage=Math.ceil(gifts.length/perPage)-1;return `<section class="room-gifts"><div class="gift-row"><div class="gift-carousel"><button class="gift-page-btn" data-gift-page="prev" ${giftPage===0?'disabled':''} aria-label="上一页礼物">‹</button><div class="gift-list">${visible.map(gift=>`<div class="gift-item"><img src="${gift.cover}" alt="${gift.name}"><div class="gift-pop"><img src="${gift.cover}" alt=""><b>${gift.name}</b><p>${gift.description}</p><strong>${gift.price}</strong><button data-gift-send="${gift.id}">赠送</button></div></div>`).join('')}</div><button class="gift-page-btn" data-gift-page="next" ${giftPage===maxPage?'disabled':''} aria-label="下一页礼物">›</button></div><div class="asset-pills"><span class="asset-tile diamond"><i>◆</i><b>2,680</b><small>钻石</small></span><span class="asset-tile coin"><i>●</i><b>8,420</b><small>金币</small></span><button class="asset-action" data-action="recharge"><i>＋</i><span>充值</span></button><button class="asset-action" data-action="bag"><i>▣</i><span>背包</span></button><button class="asset-action" data-action="noble"><i>♛</i><span>贵族</span></button></div></div></section>`}
function roomChat(room){let messages=chatMessages.map(messageLine).join('');return `<div class="chat-content"><div class="chat-scroll" id="chatScroll">${messages}</div>${entryVisible?'<div class="entry-toast">欢迎 小宇同学 进入直播间</div>':''}<form class="chat-input" id="roomChatForm"><input id="roomChatInput" maxlength="80" placeholder="说点什么吧..." autocomplete="off"><button type="submit">发送</button></form></div>`}
function roomSidebar(room){return `<aside class="room-sidebar"><div class="room-side-tabs"><button class="${roomSideTab==='chat'?'selected':''}" data-side-tab="chat">聊天室</button><button class="${roomSideTab==='private'?'selected':''}" data-side-tab="private">私聊</button><button class="${roomSideTab==='situation'?'selected':''}" data-side-tab="situation">赛况</button></div>${roomSideTab==='situation'?roomSituation(room):roomSideTab==='private'?roomPrivateChat():roomChat(room)}</aside>`}
function roomBoundMatch(room){return room.matchId?matchEvents.find(event=>event.id===room.matchId)||featuredEventDetail(room.matchId):null}
function roomSituation(room){const event=roomBoundMatch(room),supported=event&&['football','basketball'].includes(event.sport),hasData=supported&&(event.sport==='football'?footballSituationData(event).elapsed>0:basketballMatchData(event).events.length>0);return `<div class="room-situation" data-bound-match="${event?.id||''}">${hasData?matchSituation(event,{compact:true}):'<div class="detail-empty">暂无赛况信息</div>'}</div>`}
function roomPage(id){let room=roomOf(id),hostRecord=hostDirectory.find(item=>item.name===room.host),followId=hostRecord?.id||room.host,following=followedHosts.has(followId),recommended=liveStreams.filter(item=>item.id!==room.id).slice(0,8);return `${header()}<main class="room-page"><div class="room-layout"><div class="room-main"><section class="room-host"><img src="${room.avatar}" alt="${room.host}"><div class="room-host-copy"><h1>${room.title}</h1><p><span class="level-pill">Lv. ${room.presenterTag==='金牌主播'?36:24}</span><b>${room.host}</b><em>ID：${room.id}</em><span>🔥 ${room.heat}</span></p></div><div class="room-host-actions"><button class="share-btn" data-share>↗ 分享</button><button class="follow-btn ${following?'following':''}" data-follow-btn data-follow-host="${followId}">${following?'已关注':'+ 关注'} <small>${fanText(hostRecord?.fans||roomFans)}</small></button></div></section><section class="room-player ${playerPlaying?'is-playing':'is-paused'}"><img src="${room.cover}" alt="${room.title}"><div class="room-player-shade"></div>${danmakuOn?'<div class="danmaku d1">这波防守漂亮！</div><div class="danmaku d2">主播讲得好清楚</div><div class="danmaku d3">阿森纳加油！</div>':''}<div class="room-player-center">${playerPlaying?'':'▶'}</div>${playerControls()}</section>${giftSection()}<section class="room-recommend"><div class="section-head"><h2>推荐直播</h2><a href="#/live">更多 <b>›</b></a></div><div class="live-page-grid room-recommend-grid">${recommended.map(liveCard).join('')}</div></section></div>${roomSidebar(room)}</div></main><div class="app-toast" id="appToast" role="status"></div>${footer()}`}
function showToast(text){let toast=document.querySelector('#appToast');if(!toast)return;toast.textContent=text;toast.classList.add('show');clearTimeout(showToast.timer);showToast.timer=setTimeout(()=>toast.classList.remove('show'),1800)}
const eventTeam = (label, color) => `<span class="event-team-logo" style="--team-color:${color}">${label}</span>`;
function liveAnchorAvatarGroup(hosts = [], allowLive = true) {
  return `<div class="anchor-avatar-group" aria-label="已预约主播">${hosts.slice(0,3).map((value,index)=>{const host=typeof value==='object'?value:{avatarId:value};const stream=liveStreams.find(item=>item.avatar.endsWith(`img=${host.avatarId}`));const live=allowLive && (host.isLive ?? Boolean(stream));return `<span class="anchor-avatar ${live?'is-live':''}" title="${host.name||stream?.host||'预约主播'}${live?' · 正在直播':''}"><img src="${host.avatar||stream?.avatar||`https://i.pravatar.cc/80?img=${host.avatarId}`}" alt="${host.name||stream?.host||`预约主播 ${index+1}`}" loading="lazy"></span>`}).join('')}${hosts.length>3?`<span class="anchor-overflow">+${hosts.length-3}</span>`:''}</div>`;
}
function eventCard(event){ return `<a class="event-card" href="#/match/${event.id}" aria-label="查看${event.home}对${event.away}的赛事详情"><div class="event-card-top"><span class="event-league">${event.league}</span><time>${event.time}</time></div><div class="event-sides"><span class="event-team">${eventTeam(event.homeLogo,event.color)}<b>${event.home}</b></span><strong class="event-score">${event.score}</strong><span class="event-team away"><b>${event.away}</b>${eventTeam(event.awayLogo,event.color)}</span></div><div class="event-anchor-foot">${liveAnchorAvatarGroup(event.hosts)}</div></a>` }
function liveGrid(category=liveCategory){ let list=category==='全部'?liveStreams:liveStreams.filter(item=>item.category===category); return list.map(liveCard).join(''); }
