const followedHosts=new Set();
const searchKeyword=()=>{let hash=location.hash||'';return (new URLSearchParams(hash.includes('?')?hash.split('?')[1]:'')).get('keyword')?.trim()||''};
const searchStreams=()=>[...liveRooms,...hotRooms,...liveStreams,...searchExtraStreams].filter((item,index,all)=>all.findIndex(other=>other.id===item.id)===index);
const escapeHTML=(value='')=>String(value).replace(/[&<>'"]/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[char]));
const fanCount=(count)=>count>=10000?`${(count/10000).toFixed(1).replace('.0','')}万`:`${count}`;
function searchHostCard(host){let following=followedHosts.has(host.id),target=host.liveRoom?`直播中`:`未开播`;return `<article class="search-host-card" data-host-open="${host.id}" role="link" tabindex="0" aria-label="查看主播 ${host.name}"><div class="search-host-avatar ${host.liveRoom?'is-live':''}"><img src="${host.avatar}" alt="${host.name}"><i></i></div><b>${host.name}</b><small>${fanCount(host.fans)} 粉丝</small><span class="host-status ${host.liveRoom?'live':''}">${host.liveRoom?'正在直播':'暂未开播'}</span><button class="follow-btn ${following?'following':''}" data-host-follow="${host.id}">${following?'已关注':'+ 关注'}</button></article>`}
function profilePage(id){let user=id==='mock-user'?getAuthUser():null,host=hostDirectory.find(item=>item.id===id);if(user)return `${header()}<main class="subpage"><div class="subpage-card account-profile"><img src="${user.avatar}" alt="${user.nickname}"><span class="page-eyebrow">个人中心</span><h1>${user.nickname}</h1><p>用户 ID：${user.userId} · 手机号：${user.phone.slice(0,3)}****${user.phone.slice(-4)}</p><a class="go-live" href="#/live">浏览热门直播</a></div></main>${footer()}`;return `${header()}<main class="subpage"><div class="subpage-card"><span class="page-eyebrow">主播个人中心</span><h1>${host?host.name:'主播'}</h1><p>${host?`${fanCount(host.fans)} 粉丝 · 当前${host.liveRoom?'正在直播':'暂未开播'}`:'该主播信息暂未开放。'}</p>${host?.liveRoom?`<a class="go-live" href="#/room/${host.liveRoom}">进入直播间</a>`:'<a class="go-live" href="#/live">浏览直播</a>'}</div></main>${footer()}`}
function searchPage(){let keyword=searchKeyword(),needle=keyword.toLocaleLowerCase(),streams=needle?searchStreams().filter(item=>[item.title,item.category,item.league,item.host,item.presenterTag].filter(Boolean).join(' ').toLocaleLowerCase().includes(needle)):[],hosts=needle?hostDirectory.filter(host=>host.name.toLocaleLowerCase().includes(needle)):[],resultCount=streams.length+hosts.length;let content=!streams.length&&!hosts.length?`<section class="search-empty"><div>⌕</div><h1>未找到相关内容</h1><p>换个关键词试试吧</p></section>`:`${streams.length?`<section class="search-section"><div class="search-section-head"><h2>直播</h2><span>找到 ${streams.length} 个相关直播</span></div><div class="search-live-grid">${streams.map(liveCard).join('')}</div></section>`:''}${hosts.length?`<section class="search-section search-host-section"><div class="search-section-head"><h2>主播</h2><span>找到 ${hosts.length} 位相关主播</span></div><div class="search-host-grid">${hosts.map(searchHostCard).join('')}</div></section>`:''}`;return `${header()}<main class="search-page"><div class="search-page-title"><p>搜索结果</p><h1>“${escapeHTML(keyword)}”</h1><div class="search-result-summary">共找到相关结果 <b>${resultCount}</b> 个</div></div>${content}</main>${footer()}`}

function downloadPanel(){return `<section class="download-panel" aria-label="神马直播 App 下载"><div class="download-brand"><span class="brand-mark">${downloadConfig.logoLetter}</span><b>${downloadConfig.appName}</b></div><img class="download-qr" src="${downloadConfig.qrCode}" alt="神马直播 App 下载二维码"><small>扫码下载 App，随时看精彩赛事</small><a class="download-now" href="${downloadLink()}">立即下载</a><a class="download-guide-link" href="${downloadLink('#install-guide')}">查看安装教程 ›</a></section>`}
function floatingDownload(){return `<div class="floating-download"><button class="floating-download-button" type="button" aria-haspopup="dialog"><i>${icon('download')}</i><span>下载 App</span></button>${downloadPanel()}</div>`}

const footballStatItems=[['redCards','红牌'],['yellowCards','黄牌'],['corners','角球'],['penalties','点球'],['shotsOnTarget','射正'],['shotsOffTarget','射偏'],['attacks','进攻'],['dangerousAttacks','危险进攻'],['possession','控球率',true]];
const basketballStatItems=[['threePointersMade','3分'],['twoPointersMade','2分'],['freeThrowsMade','罚球'],['timeoutsRemaining','剩余暂停'],['fouls','犯规'],['freeThrowPercentage','罚球命中率',true],['totalTimeouts','总暂停']];
const footballPlayerNames=['门将 A.拉亚','后卫 B.怀特','后卫 W.萨利巴','后卫 加布里埃尔','后卫 J.廷伯','中场 D.赖斯','中场 M.厄德高','中场 K.哈弗茨','前锋 B.萨卡','前锋 G.马丁内利','前锋 G.热苏斯','门将 D.拉姆斯代尔','后卫 雅库布','中场 若日尼奥','前锋 特罗萨德'];
const basketballPlayerNames=['LeBron James','Anthony Davis','Austin Reaves','D’Angelo Russell','Rui Hachimura','Gabe Vincent','Jarred Vanderbilt','Max Christie'];
function detailAvatar(seed){return `<img src="https://i.pravatar.cc/80?img=${(seed%65)+1}" alt="" loading="lazy">`}
function matchDetailSources(e){if(e.id==='live-epl')return {animation:true,video:true};if(e.id==='live-laliga')return {animation:true,video:false};if(e.id==='live-cba')return {animation:false,video:true};return {animation:true,video:!!e.video||(e.status==='live'&&Number(e.id.replace(/\D/g,'')||0)%3===0)}}
function matchDetailStats(e){return e.sport==='football'?footballSituationData(e).statistics:basketballMatchData(e).statistics}
function detailStatRows(e){let stats=matchDetailStats(e),items=e.sport==='football'?footballStatItems:basketballStatItems;return `<div class="detail-stat-list">${items.map(([key,label,percent])=>{let [home,away]=stats[key]||[0,0],max=percent?100:Math.max(home,away,1),hp=home/max*50,ap=away/max*50;return `<article class="detail-stat-row"><div><b class="home ${home>away?'lead':''}">${percent?`${home}%`:home}</b><span>${label}</span><b class="away ${away>home?'lead':''}">${percent?`${away}%`:away}</b></div><p><i class="home" style="width:${hp}%"></i><i class="away" style="width:${ap}%"></i></p></article>`}).join('')}</div>`}
function footballNodes(start,formation,team){let rows=[1,...formation.split('-').map(Number)],pointer=0;return `<div class="detail-pitch-team ${team}">${rows.map((count,row)=>`<div class="detail-pitch-line" data-line="${row}">${Array.from({length:count},()=>{let index=(start+pointer++)%footballPlayerNames.length,name=footballPlayerNames[index];return `<span class="detail-pitch-player ${team}"><i>${pointer}</i>${detailAvatar(index+8)}<b title="${name}">${name}</b></span>`}).join('')}</div>`).join('')}</div>`}
function footballTeamHeader(e,away=false){let name=away?e.away:e.home,formation=away?'4-2-3-1':'4-3-3';return `<article class="detail-lineup-team-head ${away?'away':'home'}">${matchLogo(name,e.color)}<div><b title="${name}">${name}</b><small>阵型 ${formation}</small></div></article>`}
function benchRows(e,away=false){let names=footballPlayerNames.slice(11).map((name,i)=>`<article><b>${i+12}</b>${detailAvatar(i+(away?28:16))}<span><strong>${name}</strong><small>${["门将","中场","前锋"][i%3]} · €${35+i*8}M</small></span>${i===1?"<em>68&apos; 替补上场</em>":""}</article>`).join("");return `<section class="detail-bench"><h3>${away?e.away:e.home} 替补阵容</h3>${names}</section>`}
function footballLineup(e){return `<section class="detail-lineup football"><h3 class="detail-lineup-heading">首发阵容</h3><div class="detail-lineup-team-heads">${footballTeamHeader(e)}${footballTeamHeader(e,true)}</div><div class="detail-full-pitch-wrap"><div class="detail-full-pitch"><span class="detail-pitch-center-circle"></span><span class="detail-pitch-center-dot"></span><span class="detail-penalty-area home"></span><span class="detail-goal-area home"></span><span class="detail-penalty-area away"></span><span class="detail-goal-area away"></span>${footballNodes(16,'4-3-3','home')}${footballNodes(29,'4-2-3-1','away')}</div></div><section class="detail-coaches"><h3>教练</h3><div><article>${detailAvatar(16)}<span><b>Erik ten Hag</b><small>${e.home}</small></span></article><article>${detailAvatar(34)}<span><b>Jürgen Klopp</b><small>${e.away}</small></span></article></div></section><section class="detail-benches"><h3>替补阵容</h3><div>${benchRows(e)}${benchRows(e,true)}</div></section></section>`}

function basketballRows(e,away=false){let shift=away?6:0,roster=basketballMatchData(e).rosters[away?1:0],totals=roster.reduce((sum,player)=>({points:sum.points+player.points,rebounds:sum.rebounds+player.rebounds,assists:sum.assists+player.assists,made:sum.made+player.made,attempted:sum.attempted+player.attempted}),{points:0,rebounds:0,assists:0,made:0,attempted:0});return `<section class="detail-basket-team"><h3>${away?e.away:e.home}</h3><div class="detail-basket-head"><span>球员</span><span>得分</span><span>篮板</span><span>助攻</span><span>投篮</span></div>${roster.map((player,i)=>`<article><span><b>${[23,3,15,1,28,7,2,20][i]}</b>${detailAvatar(i+shift)}<em title="${player.name}">${player.name}</em></span><span>${player.points}</span><span>${player.rebounds}</span><span>${player.assists}</span><span>${player.made}/${player.attempted}</span></article>`).join('')}<article class="detail-basket-total"><span>全队</span><strong>${totals.points}</strong><strong>${totals.rebounds}</strong><strong>${totals.assists}</strong><strong>${totals.made}/${totals.attempted}</strong></article></section>`}
function basketballLineup(e){return `<section class="detail-lineup basketball">${basketballRows(e)}${basketballRows(e,true)}</section>`}
const footballEventLegend=[['goal','进球'],['penalty','点球'],['penaltyMiss','点球未进'],['ownGoal','乌龙球'],['assist','助攻'],['corner','角球'],['yellow','黄牌'],['red','红牌'],['secondYellow','两黄一红'],['substitution','换人'],['injury','受伤'],['var','VAR']];
const footballEventAssets={goal:new URL('../assets/match-events/goal.png',import.meta.url).href,corner:new URL('../assets/match-events/corner.png',import.meta.url).href,yellow:new URL('../assets/match-events/yellow.png',import.meta.url).href,red:new URL('../assets/match-events/red.png',import.meta.url).href};
function footballEventIcon(type){if(footballEventAssets[type])return `<img class="football-event-image" src="${footballEventAssets[type]}" alt="" />`;return {penalty:'◉',penaltyMiss:'⊘',ownGoal:'◉',assist:'↗',secondYellow:'▮',substitution:'↔',injury:'✚',var:'VAR',stage:'•'}[type]||'•'}
function footballMoment(minute){if(minute==='点球大战')return 121;let m=String(minute).match(/(\d+)(?:\+(\d+))?/);return m?Number(m[1])+Number(m[2]||0):0}
function footballEventsFor(e){if(e.status==='upcoming')return [];let home=e.home,away=e.away,seed=Number(String(e.id).replace(/\D/g,''))||0,extra=e.status==='finished'&&seed%3===0;let normal=[
{id:'final',minute:'90+5\'',type:'stage',teamSide:'neutral',stage:'终场',description:'比赛结束',homeScore:2,awayScore:1},
{id:'var',minute:'90+3\'',type:'var',teamSide:'home',teamName:home,description:'VAR确认进球有效',homeScore:2,awayScore:1},
{id:'second-yellow',minute:'88\'',type:'secondYellow',teamSide:'away',teamName:away,description:'两黄一红，被罚离场',homeScore:1,awayScore:1},
{id:'injury',minute:'82\'',type:'injury',teamSide:'home',teamName:home,description:'球员受伤，比赛暂时中断',homeScore:1,awayScore:1},
{id:'substitution',minute:'75\'',type:'substitution',teamSide:'away',teamName:away,description:'换人：A球员下，B球员上',homeScore:1,awayScore:1},
{id:'penalty-miss',minute:'69\'',type:'penaltyMiss',teamSide:'home',teamName:home,description:'点球未进',homeScore:1,awayScore:1},
{id:'penalty',minute:'68\'',type:'penalty',teamSide:'home',teamName:home,description:'获得点球',homeScore:1,awayScore:1},
{id:'corner-home',minute:'63\'',type:'corner',teamSide:'home',teamName:home,description:'获得角球',homeScore:1,awayScore:1},
{id:'goal-home',minute:'58\'',type:'goal',teamSide:'home',teamName:home,description:'前锋推射破门',homeScore:2,awayScore:1},
{id:'assist-home',minute:'58\'',type:'assist',teamSide:'home',teamName:home,description:'助攻：中场送出直塞',homeScore:2,awayScore:1},
{id:'second-start',minute:'46\'',type:'stage',teamSide:'neutral',stage:'下半场',description:'下半场开始',homeScore:1,awayScore:1},
{id:'half',minute:'45+2\'',type:'stage',teamSide:'neutral',stage:'半场',description:'上半场结束',homeScore:1,awayScore:1},
{id:'corner-away',minute:'39\'',type:'corner',teamSide:'away',teamName:away,description:'获得角球',homeScore:1,awayScore:1},
{id:'yellow',minute:'31\'',type:'yellow',teamSide:'home',teamName:home,description:'战术犯规，获得黄牌',homeScore:1,awayScore:1},
{id:'own-goal',minute:'24\'',type:'ownGoal',teamSide:'home',teamName:home,description:'乌龙球',homeScore:1,awayScore:1},
{id:'goal-away',minute:'5\'',type:'goal',teamSide:'away',teamName:away,description:'反击破门',homeScore:0,awayScore:1},
{id:'start',minute:'0\'',type:'stage',teamSide:'neutral',stage:'开始',description:'比赛开始',homeScore:0,awayScore:0}
];if(extra)normal.unshift(
{id:'extra-end',minute:'120+2\'',type:'stage',teamSide:'neutral',stage:'终场',description:'加时赛结束',homeScore:3,awayScore:2},
{id:'shootout',minute:'点球大战',type:'stage',teamSide:'neutral',stage:'点球大战',description:'进入点球大战',homeScore:3,awayScore:2},
{id:'extra-goal',minute:'118\'',type:'goal',teamSide:'away',teamName:away,description:'加时赛扳平比分',homeScore:2,awayScore:2},
{id:'extra-second',minute:'106\'',type:'stage',teamSide:'neutral',stage:'加时下半场',description:'加时赛下半场开始',homeScore:2,awayScore:1},
{id:'extra-half',minute:'105\'',type:'stage',teamSide:'neutral',stage:'加时中场',description:'加时赛上半场结束',homeScore:2,awayScore:1},
{id:'extra-start',minute:'91\'',type:'stage',teamSide:'neutral',stage:'加时赛',description:'加时赛开始',homeScore:2,awayScore:1},
{id:'regular-end',minute:'90\'',type:'stage',teamSide:'neutral',stage:'常规时间结束',description:'常规时间结束，进入加时赛',homeScore:2,awayScore:1}
);let cap=999;if(e.status==='live'){let stage=e.stage||'',m=stage.match(/(\d+)/);cap=stage.includes('中场')?47.5:m?Number(m[1]):65}return normal.filter(item=>footballMoment(item.minute)<=cap).sort((a,b)=>footballMoment(b.minute)-footballMoment(a.minute))}
function timelineTeams(e,colours=false){return `<header class="timeline-team-head ${colours?'with-colours':''}"><span>${matchLogo(e.home,e.color)}<b title="${e.home}">${e.home}</b>${colours?'<i class="home"></i>':''}</span><span>${colours?'<i class="away"></i>':''}<b title="${e.away}">${e.away}</b>${matchLogo(e.away,e.color)}</span></header>`}
function footballKeyTimeline(e,events){let score=item=>`${item.homeScore}:${item.awayScore}`;return `<section class="football-key-events">${timelineTeams(e)}<div class="football-timeline">${events.map(item=>item.type==='stage'?`<article class="football-stage"><div><time>${item.minute}</time><b>${item.stage}</b><small>${item.description}</small></div></article>`:`<article class="football-key-row"><div class="football-key-card home">${item.teamSide==='home'?`<div><b>${item.description}</b><small>${score(item)}</small></div><span class="match-event-icon ${item.type}">${footballEventIcon(item.type)}</span>`:''}</div><div class="football-key-axis"><time>${item.minute}</time><i></i></div><div class="football-key-card away">${item.teamSide==='away'?`<span class="match-event-icon ${item.type}">${footballEventIcon(item.type)}</span><div><b>${item.description}</b><small>${score(item)}</small></div>`:''}</div></article>`).join('')}</div>${footballEventLegendMarkup()}</section>`}
function footballEventLegendMarkup(){return `<footer class="football-event-legend">${footballEventLegend.map(([type,label])=>`<span><i class="match-event-icon ${type}">${footballEventIcon(type)}</i>${label}</span>`).join('')}</footer>`}
function footballTextTimeline(e,events){let sideLabel=side=>side==='home'?'主队':side==='away'?'客队':'中立',isGoal=item=>item.type==='goal'||item.type==='ownGoal',goalScore=item=>isGoal(item)?`<b class="football-goal-score"><small>当前比分：</small><span class="${item.teamSide==='home'?'scored':''}">${item.homeScore}</span><i>：</i><span class="${item.teamSide==='away'?'scored':''}">${item.awayScore}</span></b>`:'';return `<section class="football-text-live"><div class="football-text-list">${events.map(item=>`<article class="football-text-row ${item.teamSide} ${item.type==='stage'?'stage':''}"><i class="match-event-icon ${item.type}">${footballEventIcon(item.type)}</i><time>${item.minute}</time><span class="football-text-copy">${item.teamName?`${item.teamName} `:''}${item.description}${goalScore(item)}</span><em class="event-side-tag">${sideLabel(item.teamSide)}</em></article>`).join('')}</div>${footballEventLegendMarkup()}</section>`}
// One signed sample per minute; all football summaries share the same fixture model.
function footballSituationData(e){
 const events=footballEventsFor(e),seed=[...String(e.id)].reduce((n,c)=>(n*31+c.charCodeAt(0))>>>0,7);
 const elapsed=e.status==='upcoming'?0:e.status==='finished'?Math.max(90,...events.map(item=>footballMoment(item.minute))):e.stage?.includes('中场')?45:footballMoment(e.stage||'0');
 let state=seed;const random=()=>{state=(Math.imul(state,1664525)+1013904223)>>>0;return state/4294967296};
 const profiles=[[38,62,25,49,18,55,31],[-30,-55,-20,-62,-35,-18,-48],[35,-40,52,-25,14,-58,32],[4,-8,12,-3,8,-10,3],[48,35,61,22,-38,-57,-30]],profile=profiles[seed%profiles.length];
 const momentum=[];let previous=0;
 for(let minute=0;minute<=elapsed;minute+=2){const phase=minute/Math.max(elapsed,1)*(profile.length-1),i=Math.floor(phase),bias=profile[i]+((profile[i+1]??profile[i])-profile[i])*(phase-i);const goal=events.find(item=>item.type==='goal'&&Math.abs(footballMoment(item.minute)-minute)<5);let target=bias+(random()-.5)*48+(goal?(goal.teamSide==='home'?18:-18):0);previous=minute===0?0:previous*.35+target*.65;momentum.push({minute,value:Math.round(Math.max(-90,Math.min(90,previous)))});}
 if(elapsed&&momentum.at(-1).minute!==elapsed)momentum.push({minute:elapsed,value:previous});
 const mean=momentum.length?momentum.reduce((sum,p)=>sum+p.value,0)/momentum.length:0,homeShare=Math.max(25,Math.min(75,Math.round(50+mean*.32))),scale=elapsed/90;
 const pair=(total)=>[Math.round(total*homeShare/100*scale),Math.round(total*(100-homeShare)/100*scale)];
 const statistics={shots:pair(25),shotsOnTarget:pair(11),shotsOffTarget:pair(14),possession:elapsed?[homeShare,100-homeShare]:[0,0],attacks:pair(210),dangerousAttacks:pair(96),corners:elapsed?(e.corners?e.corners.split(/\s*:\s*/).map(Number):pair(10)):[0,0],yellowCards:elapsed?[e.cards?.home?.yellow??events.filter(x=>x.teamSide==='home'&&x.type==='yellow').length,e.cards?.away?.yellow??events.filter(x=>x.teamSide==='away'&&['yellow','secondYellow'].includes(x.type)).length]:[0,0],redCards:elapsed?[e.cards?.home?.red??0,e.cards?.away?.red??events.filter(x=>x.teamSide==='away'&&['red','secondYellow'].includes(x.type)).length]:[0,0],penalties:[events.filter(x=>x.type==='penalty'&&x.teamSide==='home').length,events.filter(x=>x.type==='penalty'&&x.teamSide==='away').length]};
 statistics.shots=statistics.shotsOnTarget.map((n,i)=>n+statistics.shotsOffTarget[i]);
 return {momentum,events,statistics,elapsed,home:e.home,away:e.away,color:e.color};
}
function momentumSmoothPath(points){if(!points.length)return '';let path=`M ${points[0][0]} ${points[0][1]}`;for(let i=1;i<points.length;i++){const previous=points[i-1],next=points[i];path+=` C ${(previous[0]+next[0])/2} ${previous[1]}, ${(previous[0]+next[0])/2} ${next[1]}, ${next[0]} ${next[1]}`;}return path;}
function footballMomentumMarkup(data,{compact=false}={}){
 if(!data.elapsed)return '<div class="football-momentum-empty">暂无进攻趋势数据</div>';
 const end=Math.max(90,data.elapsed),x=minute=>(compact?62:24)+minute/end*(compact?676:752),points=data.momentum.map(p=>[x(p.minute),108-p.value*.58]),path=momentumSmoothPath(points),area=`${path} L ${x(data.elapsed)} 108 L ${x(0)} 108 Z`,ticks=[];
 for(let minute=0;minute<=end;minute+=15)ticks.push(minute);
 if(end%15)ticks.push(end);
 const label=minute=>minute>120?`120+${minute-120}'`:minute>90&&end<105?`90+${minute-90}'`:`${minute}'`;
 const eventIcons=data.events.filter(item=>item.type!=='stage'&&item.teamSide!=='neutral');
 return `<div class="football-momentum"><div class="momentum-team-logos"><span class="momentum-team-logo home" title="主队：${data.home}">${matchLogo(data.home,data.color)}</span><span class="momentum-team-logo away" title="客队：${data.away}">${matchLogo(data.away,data.color)}</span></div><svg viewBox="0 0 800 208" role="img" aria-label="进攻趋势：主队向上，客队向下"><defs><clipPath id="momentum-home"><rect x="0" y="0" width="800" height="108"/></clipPath><clipPath id="momentum-away"><rect x="0" y="108" width="800" height="100"/></clipPath></defs>${ticks.map(t=>`<text class="momentum-tick" x="${x(t)}" y="16" text-anchor="middle">${label(t)}</text><line class="momentum-guide" x1="${x(t)}" x2="${x(t)}" y1="30" y2="188"/>`).join('')}<line class="momentum-baseline" x1="24" x2="776" y1="108" y2="108"/><path d="${area}" fill="#e66b61" fill-opacity=".15" clip-path="url(#momentum-home)"/><path d="${area}" fill="#528ac7" fill-opacity=".15" clip-path="url(#momentum-away)"/><path d="${path}" fill="none" stroke="#e66b61" stroke-width="2" clip-path="url(#momentum-home)"/><path d="${path}" fill="none" stroke="#528ac7" stroke-width="2" clip-path="url(#momentum-away)"/>${eventIcons.map(item=>`<g class="momentum-event" transform="translate(${x(footballMoment(item.minute))},${item.teamSide==='home'?40:180})"><title>${item.minute} · ${footballEventLegend.find(([type])=>type===item.type)?.[1]||item.type} · ${item.player||''} ${item.description}</title><rect x="-8" y="-9" width="16" height="18" rx="4" fill="#f4f6f8"/>${footballEventAssets[item.type]?`<image href="${footballEventAssets[item.type]}" x="-7" y="-7" width="14" height="14"/>`:`<text text-anchor="middle" dominant-baseline="central" class="momentum-icon ${item.type}">${footballEventIcon(item.type)}</text>`}</g>`).join('')}</svg></div>`;
}
function footballSummaryMarkup(statistics){const items=[['shots','射门'],['shotsOnTarget','射正'],['possession','控球'],['attacks','进攻'],['dangerousAttacks','危险进攻'],['corners','角球'],['yellowCards','黄牌'],['redCards','红牌']];return `<section class="football-summary" aria-label="关键事件指标"><div class="football-summary-grid">${items.map(([key,label])=>{const [home,away]=statistics[key],total=home+away,ratio=total?(key==='possession'?Math.max(home,away):Math.max(home,away)/total*100):0;return `<div class="football-summary-item"><span>${label}</span><i class="football-summary-ring" role="img" aria-label="${label} 主队 ${home}，客队 ${away}" style="--ring-fill:${total&&home!==away?`conic-gradient(from ${home>away?180:0}deg,${home>away?'#e66b61':'#528ac7'} 0% ${ratio}%,#e8edf2 ${ratio}% 100%)`:'#e8edf2'}"></i><div><b>${home}${key==='possession'?'%':''}</b><small>:</small><b>${away}${key==='possession'?'%':''}</b></div></div>`}).join('')}</div></section>`;}
function footballSituation(e,options={}){let data=footballSituationData(e),events=data.events;return `<section class="football-situation">${footballMomentumMarkup(data,options)}${footballSummaryMarkup(data.statistics)}${events.length?`<nav class="situation-tabs"><button class="${matchTimelineView==='key'?'selected':''}" data-match-timeline-view="key">关键事件</button><button class="${matchTimelineView==='text'?'selected':''}" data-match-timeline-view="text">文字直播</button></nav>${matchTimelineView==='key'?footballKeyTimeline(e,events):footballTextTimeline(e,events)}`:'<div class="detail-empty"><span>◌</span>比赛尚未开始，暂无赛况数据</div>'}</section>`}
function basketballPeriodLabel(period){return period<=4?`第${['一','二','三','四'][period-1]}节`:period===5?'加时':`OT${period-4}`}
function basketballClockValue(clock){let [m,s]=clock.split(':').map(Number);return m*60+s}
function basketballCurrentPeriod(e){return basketballMatchData(e).period}
function basketballLiveEventsFor(e){return basketballMatchData(e).events}
function basketballSituation(e,options={}){const data=basketballMatchData(e),selected=matchTimelinePeriodById[e.id];return basketballSituationMarkup(e,data,selected&&selected<=data.period?selected:data.period,matchLogo,options)}
// Both surfaces advance the same fixture ledger, without disturbing chat input.
setInterval(()=>{
 const inRoom=location.hash.startsWith('#/room/');
 if(!inRoom&&!location.hash.startsWith('#/match/'))return;
 const e=inRoom?roomBoundMatch(roomOf(location.hash.split('/').pop())):matchEvents.find(item=>item.id===activeMatchDetailId);
 if(!e||e.sport!=='basketball'||e.status!=='live')return;
 const data=basketballMatchData(e),clock=e.stage.match(/(\d+):(\d+)/);
 let period=data.period,seconds=clock?Number(clock[1])*60+Number(clock[2]):0;
 if(seconds>18)seconds-=18;
 else if(period<4||data.homeScore===data.awayScore){period++;seconds=period<=4?data.duration:300;}
 else {e.status='finished';e.completedPeriod=period;}
 e.stage=e.status==='finished'?'已结束':`${period<=4?`第${['一','二','三','四'][period-1]}节`:`OT${period-4}`} ${String(Math.floor(seconds/60)).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`;
 if(inRoom){const panel=document.querySelector('.room-situation');if(panel){panel.outerHTML=roomSituation(roomOf(location.hash.split('/').pop()));document.querySelectorAll('[data-match-timeline-period]').forEach(button=>button.onclick=()=>{matchTimelinePeriodById[e.id]=Number(button.dataset.matchTimelinePeriod);render()});}return;}
 const summary=document.querySelector('.match-detail-summary');if(summary)summary.outerHTML=matchDetailSummary(e);
 const panel=document.querySelector('.match-detail-data');if(panel){const nav=panel.firstElementChild;while(nav.nextSibling)nav.nextSibling.remove();panel.insertAdjacentHTML('beforeend',matchDetailContent(e));panel.querySelectorAll('[data-match-timeline-period]').forEach(button=>button.onclick=()=>{matchTimelinePeriodById[e.id]=Number(button.dataset.matchTimelinePeriod);render()});}
},20000);
function matchSituation(e,options={}){return e.sport==='football'?footballSituation(e,options):basketballSituation(e,options)}
function matchDetailContent(e){if(matchDetailDataTab==='timeline')return matchSituation(e);if(matchDetailDataTab==='lineup')return e.sport==='football'?footballLineup(e):basketballLineup(e);return detailStatRows(e)}
function matchDetailSummary(e){let state=e.status==='upcoming'?'未':e.status==='finished'?'完':e.stage,score=(e.sport==='basketball'?basketballMatchData(e).score:e.score)||'VS';return `<section class="match-detail-summary"><div class="match-detail-top"><span class="match-sport ${e.sport}">${e.sport==='football'?'⚽ 足球':'🏀 篮球'}</span><b>${e.league}</b><time>${e.date||matchDateKey()} ${e.time}</time><span class="match-state ${e.status==='live'?'live':''}">${e.status==='live'?'<i></i>':''}${state}</span></div><div class="match-detail-teams"><div>${matchLogo(e.home,e.color)}<b>${e.home}</b></div><strong>${score}</strong><div>${matchLogo(e.away,e.color)}<b>${e.away}</b></div></div>${e.sport==='football'&&(e.half||e.corners)?`<div class="match-detail-extras">${e.half?`半场 ${e.half}`:''}${e.corners?`<span>角球 ${e.corners}</span>`:''}</div>`:''}</section>`}
function matchSourcePanel(e){let sources=matchDetailSources(e),fallback=sources.animation?'animation':'video',current=matchDetailSourceById[e.id]||fallback,showTabs=sources.animation&&sources.video,visual=current==='video'?`<div class="detail-video-visual"><i>▶</i><b>赛事视频直播</b><small>${e.home} vs ${e.away}</small></div>`:`<div class="detail-animation-visual"><i>${e.sport==='football'?'⚽':'🏀'}</i><b>赛事动画直播</b><small>实时赛况模拟</small></div>`,tabs=showTabs?`<div class="detail-source-tabs" aria-label="赛事源切换"><button class="${current==='video'?'selected':''}" data-match-source="video">视频</button><button class="${current==='animation'?'selected':''}" data-match-source="animation">动画</button></div>`:'';return `<section class="detail-source"><div class="room-player match-source-player">${visual}${tabs}<div class="room-player-shade"></div></div></section>`}
function matchHostList(e){if(!e.hosts?.length)return `<div class="detail-empty"><span>◌</span>暂无关联主播</div>`;return `<div class="detail-host-list">${e.hosts.map((seed,index)=>{let live=e.status==='live'&&index%2===0,name=['小美解说','球场边老周','篮球阿哲','数据观察员','绿茵小雨'][index%5],avatar=`https://i.pravatar.cc/100?img=${seed}`,heat=`${(12.6-index*1.8).toFixed(1)}万`,roomId=`match-host-${e.id}-${index}`;if(live){let template=liveRooms.find(room=>room.league===e.league)||liveRooms[e.sport==='football'?0:1];matchHostRooms.set(roomId,{...template,id:roomId,title:`${e.home} vs ${e.away}`,league:e.league,host:name,avatar,heat})}return `${live?`<a href="#/room/${roomId}" aria-label="进入${name}的直播间" style="display:block;color:inherit;text-decoration:none">`:''}<article><img src="${avatar}" alt="${name}"><div><b>${name}</b><small class="${live?'is-live':''}">${live?'● 直播中':'已预约'}</small></div>${live?`<em>🔥 ${heat}</em>`:''}</article>${live?'</a>':''}`}).join('')}</div>`}
