function matchDetailPage(id){let e=matchEvents.find(x=>x.id===id)||featuredEventDetail(id);if(!e)return simplePage('赛事不存在','该赛事可能已下线或暂未开放。');if(activeMatchDetailId!==id){activeMatchDetailId=id;matchDetailDataTab='statistics';matchTimelineView='key';delete matchTimelinePeriodById[id];matchDetailSideTab=e.status==='live'&&e.hosts?.some((_,index)=>index%2===0)?'hosts':'chat';let sources=matchDetailSources(e);matchDetailSourceById[id]=e.status==='live'&&sources.video?'video':sources.animation?'animation':'video'}return `${header()}<main class="room-page match-detail-page"><div class="room-layout"><div class="room-main">${matchDetailSummary(e)}${matchSourcePanel(e)}<section class="match-detail-data"><nav><button class="${matchDetailDataTab==='statistics'?'selected':''}" data-match-data-tab="statistics">技术统计</button><button class="${matchDetailDataTab==='timeline'?'selected':''}" data-match-data-tab="timeline">赛况</button><button class="${matchDetailDataTab==='lineup'?'selected':''}" data-match-data-tab="lineup">阵容</button></nav>${matchDetailContent(e)}</section></div>${matchDetailSidebar(e)}</div></main>${footer()}`}

function header(){ const route=isDataRoute()?'#/data':location.hash||'#/'; return `<header class="site-header"><div class="header-inner"><a class="brand" href="${routeLink('#/')}" aria-label="神马直播 首页"><span class="brand-mark">S</span><span>神马直播</span></a><nav class="main-nav">${navs.map(([n,h])=>`<a href="${routeLink(h)}" class="${route===h||(h==='#/live'&&route.startsWith('#/room/'))||(h==='#/matches'&&route.startsWith('#/match/'))?'active':''}">${n}</a>`).join('')}</nav><form class="search" id="searchForm"><button class="search-submit" type="submit" aria-label="搜索">${icon('search')}</button><input id="searchInput" value="${escapeHTML(searchKeyword())}" placeholder="请输入搜索内容" autocomplete="off"></form><div class="header-actions"><button class="utility" data-action="game"><i>${icon('game')}</i>游戏</button><div class="download-entry"><a class="utility download-trigger" href="${downloadLink()}" aria-label="前往 App 下载页"><i>${icon('download')}</i>下载 App</a>${downloadPanel()}</div><button class="go-live" ${getAuthUser()?"data-action=\"cast\"":"data-auth-open=\"login\""}>${icon('cast')} 开播</button>${authHeaderArea()}</div></div></header>${authModal()}`; }
