function footballTable(showHeading=true){let data=standings.football[footballLeague]; return `<div class="rank-card football-rank"><div class="rank-tabs">${Object.keys(standings.football).map(x=>`<button class="${x===footballLeague?'selected':''}" data-football="${x}">${x}</button>`).join('')}</div>${showHeading?`<div class="rank-title"><span>足球球队排行</span><small>${footballLeague} · 2023/24</small></div>`:''}<div class="rank-table football-table"><div class="rank-row table-head"><span class="team-column-head">球队</span><span aria-hidden="true"></span><span>赛</span><span>胜</span><span>平</span><span>负</span><span>进/失</span><span>积分</span></div>${data.map((t,i)=>`<a href="#/team/${encodeURIComponent(t[1])}" class="rank-row"><span class="rank-num n${i+1}">${i+1}</span><span class="team">${teamMark(t[0],t[1])}<b>${teamName(t[0],t[1])}</b></span><span>${t[2]}</span><span>${t[3]}</span><span>${t[4]}</span><span>${t[5]}</span><span>${t[6]}</span><strong>${t[7]}</strong></a>`).join('')}</div></div>`}
function basketballTable(showHeading=true){ let list=basketballLeague==='NBA'?standings.basketball.NBA[nbaConference]:standings.basketball.CBA.all; return `<div class="rank-card basketball-rank"><div class="rank-tabs"><button class="${basketballLeague==='NBA'?'selected':''}" data-basketball="NBA">NBA</button><button class="${basketballLeague==='CBA'?'selected':''}" data-basketball="CBA">CBA</button></div>${showHeading||basketballLeague==='NBA'?`<div class="rank-title ${showHeading?'':'rank-controls-only'}">${showHeading?'<span>篮球球队排行</span>':''}${basketballLeague==='NBA'?`<div class="conference"><button class="${nbaConference==='east'?'on':''}" data-conf="east">东部</button><button class="${nbaConference==='west'?'on':''}" data-conf="west">西部</button></div>`:'<small>常规赛</small>'}</div>`:''}<div class="rank-table basketball-table"><div class="rank-row table-head"><span class="team-column-head">球队</span><span aria-hidden="true"></span><span>胜</span><span>负</span><span>胜率</span><span>胜差</span><span>近况</span></div>${list.map((t,i)=>`<a href="#/team/${encodeURIComponent(t[1])}" class="rank-row"><span class="rank-num n${i+1}">${i+1}</span><span class="team">${teamMark(t[0],t[1])}<b>${teamName(t[0],t[1])}</b></span><span>${t[2]}</span><span>${t[3]}</span><span>${winRate(t[4])}</span><span>${t[5]}</span><span class="form">${t[6]}</span></a>`).join('')}</div></div>`}
function footer(){return `<footer class="site-footer"><div class="footer-inner"><nav class="footer-links" aria-label="页脚导航"><a href="${routeLink('#/live')}">热门直播</a><a href="${routeLink('#/matches')}">体育赛事</a><a href="${downloadLink()}">下载 App</a></nav><div class="footer-filing"><span>粤ICP备12345643号</span><i>|</i><span>粤网文（2022）2987-349号</span><i>|</i><span>增值电信业务经营许可证：粤B2-324342</span></div></div></footer>`}
function teamRanking(sport=null){return sport?`<div class="data-ranking">${sport==='football'?footballTable(false):basketballTable(false)}</div>`:`<div class="ranking-grid">${footballTable()}${basketballTable()}</div>`}
function dataPage(){return `${header()}<main class="data-page"><nav class="live-category-tabs data-sport-tabs" role="tablist" aria-label="数据体育分类">${[['football','足球'],['basketball','篮球']].map(([id,label])=>`<button class="${dataSport===id?'selected':''}" data-data-sport="${id}" role="tab" aria-selected="${dataSport===id}">${label}</button>`).join('')}</nav>${teamRanking(dataSport)}</main>${footer()}`}
function home(){return `${header()}<main><div class="featured-wrap">${featured()}</div><section class="content-section hot">${sectionHead('热门直播')}<div class="live-grid">${hotRooms.map(liveCard).join('')}</div></section><section class="content-section standings">${sectionHead('数据','#/data')}${teamRanking()}</section></main>${floatingDownload()}${footer()}`}
function appDownloadPage(){return createDownloadPage({header,footer,images:{football:liveRooms[0].cover,basketball:liveRooms[1].cover,footballAlt:liveRooms[2].cover,tennis:liveStreams.find(item=>item.category==='网球').cover,esports:liveStreams.find(item=>item.category==='英雄联盟').cover}})}
function simplePage(kind, text){return `${header()}<main class="subpage"><div class="subpage-card"><span class="page-eyebrow">SMLIVE WEB</span><h1>${kind}</h1><p>${text}</p><a class="go-live" href="#/">返回首页</a></div></main>${footer()}`}
function serviceChat(id=selectedServiceChatId){return serviceChats.find(chat=>chat.id===id)||serviceChats[0]}
function serviceChatItem(chat){let selected=chat.id===(location.hash.startsWith('#/room/')?roomPrivateChatId:selectedServiceChatId),latest=chat.messages.at(-1);return `<button class="service-chat-item ${selected?'selected':''}" data-service-chat="${chat.id}" aria-pressed="${selected}"><span class="service-avatar"><img src="${chat.avatar}" alt="${chat.name}"><i class="${chat.status}"></i></span><span class="service-chat-copy"><span class="service-chat-name"><b>${chat.name}</b><time>${chat.time}</time></span><span class="service-chat-preview"><small>${escapeChatText(latest?.text||chat.preview)}</small>${chat.unread? `<i class="service-unread" aria-label="${chat.unread}条未读消息">${chat.unread}</i>`:''}</span></span></button>`}
function serviceChatList(){return `<div class="service-chat-list-scroll">${serviceChats.map(serviceChatItem).join('')}</div>`}
function escapeChatText(text){return String(text).replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]))}
function serviceMessage(message,chat){return `<article class="service-message ${message.side}"><div class="message-avatar">${message.side==='service'?`<img src="${chat.avatar}" alt="${chat.name}">`:'我'}</div><div class="message-copy"><span class="message-sender">${message.side==='service'?chat.name:'我'} <time>${message.time}</time></span><p>${escapeChatText(message.text)}</p></div></article>`}
function serviceChatDetail(chat,{back=false}={}){return `<section class="service-chat-detail"><header class="service-chat-detail-head">${back?'<button class="service-back" data-private-back aria-label="返回客服列表">‹</button>':''}<span class="service-avatar large"><img src="${chat.avatar}" alt="${chat.name}"><i class="${chat.status}"></i></span><span><h2>${chat.name}</h2><p><i class="${chat.status}"></i>${chat.status==='online'?'在线 · 通常即时回复':'离线 · 工作时间将尽快回复'}</p></span></header><div class="service-message-area" id="serviceMessageArea">${chat.messages.map(message=>serviceMessage(message,chat)).join('')}</div><form class="service-compose" id="serviceChatForm"><div><input id="serviceChatInput" maxlength="300" placeholder="输入消息" autocomplete="off" aria-label="聊天消息"></div><button type="submit" disabled>发送</button></form></section>`}
function roomPrivateChat(){return `<div class="room-private">${roomPrivateChatId?serviceChatDetail(serviceChat(roomPrivateChatId),{back:true}):serviceChatList()}</div>`}
function refreshPrivateChat(){const panel=document.querySelector('.room-private');if(panel){panel.outerHTML=roomPrivateChat();bindServiceChat()}}
function chatPage(){let chat=serviceChat();chat.unread=0;return `${header()}<main class="service-chat-page"><section class="service-chat-shell" aria-label="客服聊天"><aside class="service-chat-list"><header><div><h1>聊天</h1></div><span>${serviceChats.length} 条会话</span></header>${serviceChatList()}</aside>${serviceChatDetail(chat)}</section></main>`}
function bindServiceChat(){
 const inRoom=location.hash.startsWith('#/room/');
 document.querySelectorAll('[data-service-chat]').forEach(button=>button.onclick=()=>{const id=button.dataset.serviceChat;serviceChat(id).unread=0;selectedServiceChatId=id;if(inRoom){roomPrivateChatId=id;refreshPrivateChat()}else render()});
 document.querySelector('[data-private-back]')?.addEventListener('click',()=>{roomPrivateChatId=null;refreshPrivateChat()});
 let input=document.querySelector('#serviceChatInput'),form=document.querySelector('#serviceChatForm'),send=form?.querySelector('button');
 if(input&&send){let sync=()=>send.disabled=!input.value.trim();input.addEventListener('input',sync);sync()}
 form?.addEventListener('submit',event=>{event.preventDefault();let text=input.value.trim();if(!text)return;let chat=serviceChat(inRoom?roomPrivateChatId:selectedServiceChatId),now=new Date(),time=new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Kuala_Lumpur',hour:'2-digit',minute:'2-digit',hour12:false}).format(now);chat.messages.push({side:'user',text,time});chat.preview=text;chat.time=time;chat.unread=0;if(inRoom)refreshPrivateChat();else render()});
 requestAnimationFrame(()=>{let area=document.querySelector('#serviceMessageArea');if(area)area.scrollTop=area.scrollHeight});
}
function detailPage(type, id){ return `${header()}<main class="subpage"><div class="detail-card"><div><span class="tag">球队</span><h1>${decodeURIComponent(id)} 球队详情</h1><p>球队 ID：${decodeURIComponent(id)}。后续将在此接入赛程、阵容、新闻与数据。</p><a class="go-live" href="#/matches">查看赛事排行</a></div></div></main>${footer()}`}
function render(){let h=location.hash||'#/'; if(isDownloadRoute()) app.innerHTML=appDownloadPage(); else if(isDataRoute()) app.innerHTML=dataPage(); else if(h==='#/'||h==='') app.innerHTML=home(); else if(h==='#/live') app.innerHTML=livePage(); else if(h==='#/schedule') app.innerHTML=schedulePage(); else if(h==='#/matches') app.innerHTML=matchesPage(); else if(h==='#/chat') app.innerHTML=chatPage(); else if(h.startsWith('#/search')) app.innerHTML=searchPage(); else if(h.startsWith('#/profile/')) app.innerHTML=profilePage(h.split('/').pop()); else if(h.startsWith('#/match/')) app.innerHTML=matchDetailPage(h.split('/').pop()); else if(h.startsWith('#/room/'))app.innerHTML=roomPage(h.split('/').pop()); else if(h.startsWith('#/team/'))app.innerHTML=detailPage('team',h.split('/').pop()); else {let map={'#/matches':['赛事','赛事中心与完整球队排行已为后续开发预留。'],'#/chat':['聊天','与球迷一起，聊你所热爱的比赛。']}; app.innerHTML=simplePage(...(map[h]||['页面不存在','请返回首页继续浏览。']));} bind(); }
function bind(){document.querySelectorAll('[data-data-sport]').forEach(button=>button.onclick=()=>{dataSport=button.dataset.dataSport;render()});bindAuth(render);bindDownloadPage();bindServiceChat();document.querySelectorAll('[data-match-sport]').forEach(b=>b.onclick=()=>{matchLeagueFilters[matchSport]=new Set(matchLeagues);matchSport=b.dataset.matchSport;matchLeagues=new Set(matchLeagueFilters[matchSport]||[]);matchFilterOpen=false;render()});document.querySelectorAll('[data-match-tab]').forEach(b=>b.onclick=()=>{matchTab=b.dataset.matchTab;render()});document.querySelectorAll('[data-match-date]').forEach(b=>b.onclick=()=>{matchTab==='schedule'?matchScheduleDate=b.dataset.matchDate:matchResultDate=b.dataset.matchDate;render()});document.querySelector('[data-match-filter]')?.addEventListener('click',()=>{if(matchFilterOpen){matchFilterOpen=false;render();return}matchDraftLeagues=new Set(matchLeagues);matchFilterOpen=true;render()});document.querySelectorAll('[data-match-filter-close]').forEach(b=>b.addEventListener('click',()=>{matchFilterOpen=false;render()}));document.querySelectorAll('[data-match-league]').forEach(b=>b.onclick=()=>{let x=b.dataset.matchLeague;matchDraftLeagues.has(x)?matchDraftLeagues.delete(x):matchDraftLeagues.add(x);refreshMatchDraftUI()});document.querySelectorAll('[data-match-select]').forEach(b=>b.onclick=()=>{let leagues=[...new Set(matchEvents.filter(e=>matchSport==='recommend'||matchType(e)===matchSport).map(e=>e.league))];if(b.dataset.matchSelect==='all')matchDraftLeagues=new Set(leagues);else matchDraftLeagues=new Set(leagues.filter(x=>!matchDraftLeagues.has(x)));refreshMatchDraftUI()});document.querySelectorAll('[data-match-reset]').forEach(b=>b.onclick=()=>{matchDraftLeagues.clear();refreshMatchDraftUI()});document.querySelector('[data-match-confirm]')?.addEventListener('click',()=>{matchLeagues=new Set(matchDraftLeagues);matchLeagueFilters[matchSport]=new Set(matchLeagues);matchFilterOpen=false;render()});
document.querySelectorAll('[data-match-follow]').forEach(b=>b.onclick=e=>{e.preventDefault();e.stopPropagation();let x=b.dataset.matchFollow;followedMatches.has(x)?followedMatches.delete(x):followedMatches.add(x);render()});
document.querySelectorAll('[data-match-source]').forEach(button=>button.onclick=()=>{matchDetailSourceById[activeMatchDetailId]=button.dataset.matchSource;render()});document.querySelectorAll('[data-match-data-tab]').forEach(button=>button.onclick=()=>{matchDetailDataTab=button.dataset.matchDataTab;render()});document.querySelectorAll('[data-match-timeline-view]').forEach(button=>button.onclick=()=>{matchTimelineView=button.dataset.matchTimelineView;render()});document.querySelectorAll('[data-match-timeline-period]').forEach(button=>button.onclick=()=>{const id=button.closest('[data-bound-match]')?.dataset.boundMatch||activeMatchDetailId;matchTimelinePeriodById[id]=Number(button.dataset.matchTimelinePeriod);render()});document.querySelectorAll('[data-match-side]').forEach(button=>button.onclick=()=>{matchDetailSideTab=button.dataset.matchSide;render()});
document.querySelectorAll('[data-schedule-day]').forEach(button=>button.onclick=()=>{scheduleDay=button.dataset.scheduleDay;render()});document.querySelectorAll('[data-schedule-sport]').forEach(button=>button.onclick=()=>{scheduleSport=button.dataset.scheduleSport;render()});document.querySelectorAll('[data-live-category]').forEach(button=>button.onclick=()=>{liveCategory=button.dataset.liveCategory;document.querySelectorAll('[data-live-category]').forEach(item=>{let selected=item.dataset.liveCategory===liveCategory;item.classList.toggle('selected',selected);item.setAttribute('aria-selected',selected)});let grid=document.querySelector('#liveGrid');if(grid)grid.innerHTML=liveGrid()});document.querySelectorAll('[data-channel]').forEach(b=>b.onclick=()=>{activeLive=+b.dataset.channel;render(); window.scrollTo({top:0,behavior:'smooth'})});document.querySelectorAll('[data-football]').forEach(b=>b.onclick=()=>{footballLeague=b.dataset.football;render()});document.querySelectorAll('[data-basketball]').forEach(b=>b.onclick=()=>{basketballLeague=b.dataset.basketball;render()});document.querySelectorAll('[data-conf]').forEach(b=>b.onclick=()=>{nbaConference=b.dataset.conf;render()});document.querySelector('[data-follow-btn]')?.addEventListener('click',button=>{let id=button.currentTarget.dataset.followHost;if(followedHosts.has(id))followedHosts.delete(id);else followedHosts.add(id);render()});document.querySelectorAll('[data-host-follow]').forEach(button=>button.onclick=event=>{event.preventDefault();event.stopPropagation();let host=hostDirectory.find(item=>item.id===button.dataset.hostFollow);if(followedHosts.has(host.id)){followedHosts.delete(host.id);host.fans-=1}else{followedHosts.add(host.id);host.fans+=1}render()});document.querySelectorAll('[data-host-open]').forEach(card=>{let open=()=>{let host=hostDirectory.find(item=>item.id===card.dataset.hostOpen);location.hash=host.liveRoom?`#/room/${host.liveRoom}`:`#/profile/${host.id}`};card.onclick=open;card.onkeydown=event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();open()}}});document.querySelector('[data-share]')?.addEventListener('click',()=>{navigator.clipboard?.writeText(location.href).catch(()=>{});showToast('链接复制成功')});document.querySelectorAll('[data-player]').forEach(button=>button.onclick=()=>{let action=button.dataset.player;if(action==='play')playerPlaying=!playerPlaying;if(action==='mute')playerMuted=!playerMuted;if(action==='danmaku')danmakuOn=!danmakuOn;if(action==='quality')qualityOpen=!qualityOpen;if(action==='fullscreen')showToast('已进入全屏模式（原型演示）');render()});document.querySelectorAll('[data-quality]').forEach(button=>button.onclick=()=>{quality=button.dataset.quality;qualityOpen=false;render()});document.querySelector('[data-player-volume]')?.addEventListener('input',event=>{playerMuted=Number(event.target.value)===0;});document.querySelectorAll('[data-side-tab]').forEach(button=>button.onclick=()=>{roomSideTab=button.dataset.sideTab;render()});document.querySelector('#roomChatForm')?.addEventListener('submit',event=>{event.preventDefault();let input=document.querySelector('#roomChatInput'),text=input.value.trim();if(!text)return;chatMessages.push({vip:'VIP 1',badge:'新球迷',name:'我',text});render();setTimeout(()=>{let box=document.querySelector('#chatScroll');if(box)box.scrollTop=box.scrollHeight},0)});document.querySelectorAll('[data-gift-page]').forEach(button=>button.onclick=()=>{giftPage=Math.max(0,Math.min(Math.ceil(gifts.length/8)-1,giftPage+(button.dataset.giftPage==='next'?1:-1)));render()});document.querySelectorAll('[data-gift-send]').forEach(button=>button.onclick=()=>{let gift=gifts.find(item=>item.id===button.dataset.giftSend);showToast(`已赠送${gift.name}`)});document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>{let a=b.dataset.action;if(a==='game')goRoute('#/game'); else if(a==='app-download')location.href=downloadLink(); else if(a==='cast')goRoute('#/creator'); else if(a==='watch')showToast('直播播放功能已就绪（原型演示）'); else if(a==='logout')showToast('已退出登录（原型演示）'); else if(['recharge','bag','noble'].includes(a))showToast({recharge:'充值中心已打开（原型演示）',bag:'背包已打开（原型演示）',noble:'贵族中心已打开（原型演示）'}[a])});let avatar=document.querySelector('#avatarBtn'),menu=document.querySelector('#userMenu');if(avatar)avatar.onclick=e=>{e.stopPropagation();menu.classList.toggle('open')};document.onclick=e=>{if(menu&&!menu.contains(e.target))menu.classList.remove('open');if(matchFilterOpen&&!e.target.closest('.match-filter-popover')&&!e.target.closest('[data-match-filter]')){matchFilterOpen=false;render()}};document.querySelector('#searchForm')?.addEventListener('submit',event=>{event.preventDefault();let q=document.querySelector('#searchInput').value.trim();if(q)goRoute(`#/search?keyword=${encodeURIComponent(q)}`)});if(entryVisible&&document.querySelector('.entry-toast'))setTimeout(()=>{entryVisible=false;document.querySelector('.entry-toast')?.remove()},3000)}
window.addEventListener('hashchange',()=>{activeLive=0;render();window.scrollTo({top:0,behavior:'smooth'})});render();
